std::stack<std::tuple<double, double, double, double, double>> intervals;
intervals.push(std::make_tuple(a, b, 0.0, (b - a) * std::abs(f((a + b) / 2.0)), 0.0));

double result = 0.0;
while (!intervals.empty() && std::abs(result) < std::numeric_limits<double>::max()) {
    auto [a_i, b_i, left, right, integral] = intervals.top();
    intervals.pop();

    double c = (a_i + b_i) / 2.0;
    double h = (b_i - a_i) / 2.0;
    double f_c = f(c);
    double f_left = f((a_i + c) / 2.0);
    double f_right = f((c + b_i) / 2.0);

    double new_integral = (left + right) / 2.0 + h * (f_left + f_right);
    double error = std::abs(new_integral - integral) / 3.0;

    if (error < precision || (b_i - a_i) < precision) {
        result += new_integral;
    } else {
        if (intervals.size() >= MAX_DEPTH) {
            result += integral;
            break;
        }
        intervals.push(std::make_tuple(a_i, c, left, h * f_left, integral));
        intervals.push(std::make_tuple(c, b_i, right, h * f_right, integral));
    }
}
return result;
